import{_ as a,o as s,c as r,a3 as l}from"./chunks/framework.Cc-oPviL.js";const u=JSON.parse('{"title":"02 · 切块与入库：资料怎么放进向量库","description":"","frontmatter":{},"headers":[],"relativePath":"ai/rag/02.md","filePath":"ai/rag/02.md"}'),o={name:"ai/rag/02.md"};function i(e,t,n,d,h,c){return s(),r("div",null,[...t[0]||(t[0]=[l(`<h1 id="_02-·-切块与入库-资料怎么放进向量库" tabindex="-1">02 · 切块与入库：资料怎么放进向量库 <a class="header-anchor" href="#_02-·-切块与入库-资料怎么放进向量库" aria-label="Permalink to &quot;02 · 切块与入库：资料怎么放进向量库&quot;">​</a></h1><blockquote><p><strong>学完你能说出</strong>：</p><ul><li>块切大了、切小了各有什么问题，常见的块大小和重叠怎么定。</li><li>为什么相邻块之间要有「重叠」。</li><li>入库时除了向量，还要存什么（原文、元数据），为什么。</li></ul></blockquote><h2 id="先看地图" tabindex="-1">先看地图 <a class="header-anchor" href="#先看地图" aria-label="Permalink to &quot;先看地图&quot;">​</a></h2><p>上一篇讲了 RAG 的完整流程。这一篇放大<strong>离线阶段</strong>：资料怎么切、怎么存。</p><p>RAG 效果不好，很多时候问题出在这一步：切坏了，后面检索再好也找不回来。</p><p>本篇讲 4 个点：① 块大小怎么定 → ② 重叠为什么要有 → ③ 按什么切 → ④ 入库存什么。</p><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p><strong>切块 = 把长文档切成「一块讲一件事」的小段；入库 = 给每块算向量，和原文、出处一起存好。</strong></p><h2 id="生活类比-做读书卡片" tabindex="-1">生活类比：做读书卡片 <a class="header-anchor" href="#生活类比-做读书卡片" aria-label="Permalink to &quot;生活类比：做读书卡片&quot;">​</a></h2><p>准备考试时，你会把教材抄成一张张知识卡片：</p><ul><li>一张卡片抄<strong>一整章</strong>：找的时候拿到一大堆，重点被淹没（块太大）。</li><li>一张卡片只抄<strong>半句话</strong>：拿到了也看不懂前因后果（块太小）。</li><li>好的卡片：<strong>一张讲清一个知识点</strong>，卡片角上写着「第几章第几页」（元数据）。</li></ul><h2 id="一步步看-切一份-3000-字的手册" tabindex="-1">一步步看：切一份 3000 字的手册 <a class="header-anchor" href="#一步步看-切一份-3000-字的手册" aria-label="Permalink to &quot;一步步看：切一份 3000 字的手册&quot;">​</a></h2><p><strong>设定</strong>：块大小 = 500 字，重叠 = 50 字。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 块：第    1 – 500 字</span></span>
<span class="line"><span>第 2 块：第  451 – 950 字     ← 往回多带 50 字</span></span>
<span class="line"><span>第 3 块：第  901 – 1400 字</span></span>
<span class="line"><span>……</span></span></code></pre></div><p>每块往后挪 450 字（500 − 50），所以 3000 字大约切成 <strong>7 块</strong>。</p><p><strong>为什么要重叠？</strong> 假设「年假规定：入职满一年」在第 1 块末尾，「可享 5 天带薪假」在第 2 块开头。不重叠的话，这句话被切成两半，哪一块都不完整；有 50 字重叠，第 2 块开头就带上了前半句。</p><p><strong>入库时每块存这些：</strong></p><table tabindex="0"><thead><tr><th>字段</th><th>例子</th><th>用途</th></tr></thead><tbody><tr><td>向量</td><td>[0.12, −0.03, …]（768 个数）</td><td>用来检索</td></tr><tr><td>原文</td><td>「员工入职满一年，享有带薪年假 5 天……」</td><td>拼进提示词给模型看</td></tr><tr><td>元数据（Metadata）</td><td>来源：员工手册.pdf，第 12 页，章节「假期」，更新日期 2026-09</td><td>显示出处、按条件筛选、删除旧版本</td></tr></tbody></table><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="为什么块大小要折中" tabindex="-1">为什么块大小要折中？ <a class="header-anchor" href="#为什么块大小要折中" aria-label="Permalink to &quot;为什么块大小要折中？&quot;">​</a></h3><ul><li><strong>块太大</strong>：一块里混了好几个话题，向量变成「平均意思」，和具体问题的相似度反而不高；拼进提示词也费 Token。</li><li><strong>块太小</strong>：语义不完整，检索到了也答不了；块数暴增，库变大。</li><li><strong>方案</strong>：取中间值，常见在<strong>几百到一千字（或 Token）左右</strong>，再按实际问答效果调。</li><li><strong>好处</strong>：每块语义完整，检索又准。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>块太大语义被稀释、检索不准还费 Token，块太小信息不完整；取能讲完一个知识点的大小，再用测试问题调参。</p></div><h3 id="为什么要重叠" tabindex="-1">为什么要重叠？ <a class="header-anchor" href="#为什么要重叠" aria-label="Permalink to &quot;为什么要重叠？&quot;">​</a></h3><ul><li><strong>问题</strong>：按固定长度硬切，会把一句话、一个要点从中间切断。</li><li><strong>方案</strong>：相邻块之间重叠一小段，常见是块大小的 10%–20%。</li><li><strong>好处</strong>：被切断的信息至少能在一块里保持完整。代价是存储多了一点。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>防止关键句被切断在两块边界上，重叠让边界附近的信息至少在一块里是完整的。</p></div><h3 id="为什么最好按结构切-而不是只按字数切" tabindex="-1">为什么最好按结构切，而不是只按字数切？ <a class="header-anchor" href="#为什么最好按结构切-而不是只按字数切" aria-label="Permalink to &quot;为什么最好按结构切，而不是只按字数切？&quot;">​</a></h3><ul><li><strong>问题</strong>：只按字数切，会把标题和正文、表格的表头和内容分开。</li><li><strong>方案</strong>：优先按文档结构切：标题、段落、列表、表格；一节太长，再按字数细分。很多工具的「递归切分」就是这个思路：先按段落切，太长再按句子切。</li><li><strong>好处</strong>：每块都是一个自然的语义单元，标题还能作为上下文。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>按标题、段落等结构切，能让每块对应一个完整话题，比机械按字数切更准；太长的节再按长度细分。</p></div><h3 id="为什么要存元数据" tabindex="-1">为什么要存元数据？ <a class="header-anchor" href="#为什么要存元数据" aria-label="Permalink to &quot;为什么要存元数据？&quot;">​</a></h3><ul><li><strong>问题</strong>：只有向量和原文的话，回答时没法告诉用户「出自哪里」；资料更新时也找不到旧版本在哪。</li><li><strong>方案</strong>：每块带上来源、页码、章节、日期等元数据。</li><li><strong>好处</strong>：能给出处；能<strong>过滤</strong>（比如只在「2026 版手册」里搜）；能<strong>增量更新</strong>（删掉某个文件的旧块，再插入新的）。</li></ul><div class="tip custom-block"><p class="custom-block-title">一句话答法</p><p>元数据让回答能溯源、检索能按条件过滤、资料能按文件增量更新。</p></div><h2 id="英文术语拆解" tabindex="-1">英文术语拆解 <a class="header-anchor" href="#英文术语拆解" aria-label="Permalink to &quot;英文术语拆解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>拆开看</th><th>一句话意思</th></tr></thead><tbody><tr><td>Chunking</td><td>chunk 块 + -ing</td><td>切块</td></tr><tr><td>Chunk Size</td><td>chunk 块 + size 大小</td><td>每块多长</td></tr><tr><td>Overlap</td><td>over 越过 + lap 重叠部分</td><td>相邻块重叠的长度</td></tr><tr><td>Recursive Splitter</td><td>recursive 递归的 + splitter 切分器</td><td>先按大单位切，太长再按小单位切</td></tr><tr><td>Metadata</td><td>meta 关于…的 + data 数据</td><td>元数据：描述数据的数据，如来源、页码</td></tr><tr><td>Indexing</td><td>index 索引 + -ing</td><td>建索引：把块向量化并入库的过程</td></tr><tr><td>Ingestion</td><td>ingest 摄入</td><td>数据导入：加载、清洗、切块、入库的全过程</td></tr></tbody></table><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：chunk size 怎么选？</strong></p><blockquote><p>没有通用最优值，取决于文档类型和问题类型。原则是一块能完整讲清一个知识点：问答类常从几百 Token 起步，配 10%–20% 的重叠，再用一组测试问题比较检索命中率来调。结构清晰的文档优先按标题、段落切。</p></blockquote><p><strong>Q：为什么要设置 overlap？</strong></p><blockquote><p>防止关键信息被切在两块的边界上导致语义不完整。代价是存储和计算略有增加。</p></blockquote><p><strong>Q：表格、PDF 这种复杂文档怎么处理？</strong></p><blockquote><p>先做好解析：PDF 要处理分栏、页眉页脚；表格尽量保持整行整表，或转成「表头: 值」的文本；图片可以用 OCR 或多模态模型生成描述。解析质量往往比切块参数影响更大。</p></blockquote><h2 id="容易混的地方" tabindex="-1">容易混的地方 <a class="header-anchor" href="#容易混的地方" aria-label="Permalink to &quot;容易混的地方&quot;">​</a></h2><ul><li><strong>块越小越精确 ✗</strong>：太小会丢上下文。「5 天」单独成块，模型不知道是什么 5 天。</li><li><strong>重叠越大越好 ✗</strong>：重叠太大，几乎重复存储，检索结果里还会出现好几块雷同内容。</li><li><strong>只要切块，不管解析 ✗</strong>：PDF 解析乱码、表格错位，切得再好也没用。<strong>垃圾进，垃圾出。</strong></li></ul><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>← 来自</strong> <a href="/study-hub/ai/rag/01">RAG 是什么</a>：这里是离线阶段的展开。</li><li><strong>← 来自</strong> <a href="/study-hub/ai/llm/03">Embedding</a>：每块用 Embedding 模型算向量。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/rag/03">检索与重排</a>：切块质量直接决定能不能检索到完整答案。</li><li><strong>→ 影响</strong> <a href="/study-hub/ai/rag/04">评估与常见坑</a>：答不好时，第一个要查的就是切块。</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：块太大、太小分别有什么问题？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>太大</strong>：一块混好几个话题，向量被「平均」、检索不准，还费 Token。<strong>太小</strong>：语义不完整，检索到了也答不了，块数暴增。要取能讲完一个知识点的大小。</p></details><p><strong>Q2：块大小 500、重叠 50，第 2 块从第几个字开始？为什么要重叠？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>从第 <strong>451</strong> 个字开始（每块往后挪 500 − 50 = 450）。重叠是为了防止关键句被切断在边界上。</p></details><p><strong>Q3：入库时为什么要存元数据？举两个用途。</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>① 回答时给出处（哪个文件、第几页）；② 检索时按条件过滤（比如只搜某个版本）；③ 资料更新时按文件删掉旧块再插入新块。任答两个即可。</p></details><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能用「读书卡片」类比说清块大小的折中</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能算出给定块大小和重叠时，每块的起止位置</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能讲清重叠、按结构切、存元数据分别解决什么问题</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能说出入库时每块要存的三类东西</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能举出至少 2 个「切块之前的解析」会出的问题</li></ul><h2 id="下一步该懂什么" tabindex="-1">下一步该懂什么 <a class="header-anchor" href="#下一步该懂什么" aria-label="Permalink to &quot;下一步该懂什么&quot;">​</a></h2><ul><li>库建好了，问题来了怎么找？只靠向量够不够？→ <a href="/study-hub/ai/rag/03">检索与重排</a></li></ul>`,55)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
